package ama.config.json;
import ama.config.*;import ama.contract.ConfigArchiveContracts.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DocumentImportConfigTest {
 @Test void documentProfilesAreExplicitAndLegacyTxtBytesRemainAccepted()throws Exception{for(String[] entry:new String[][]{{"document-parser-v1","PARSER_CONFIG","ama.office-documents.v1"},{"document-processing-v1","PROCESSING_CONFIG","ama.import-documents.v1"}}){try(var in=DocumentImportConfigTest.class.getResourceAsStream("/ama/transcript/"+entry[0]+".json")){var raw=in.readAllBytes();var state=ConfigWireReaderTest.state();assertDoesNotThrow(()->new StrictConfigArchiveReader().read(state.capture(raw,false),new Identity(ArtifactType.valueOf(entry[1]),entry[2]),state));}}var state=ConfigWireReaderTest.state();assertDoesNotThrow(()->new StrictConfigArchiveReader().read(state.capture(ConfigWireReaderTest.fixture("parser"),false),new Identity(ArtifactType.PARSER_CONFIG,"ama.strict-utf8-lines.v1"),state));}
 @Test void profileCannotSilentlyChangeItsEngineOrClaimAdditionalFormats()throws Exception{try(var in=DocumentImportConfigTest.class.getResourceAsStream("/ama/transcript/document-parser-v1.json")){String raw=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String bad:new String[]{raw.replace("3.0.8","2.0.0"),raw.replace("\"PPTX\"","\"MP3\"")}){var state=ConfigWireReaderTest.state();assertThrows(ama.contract.MinutesContracts.Failure.class,()->new StrictConfigArchiveReader().read(state.capture(bad.getBytes(StandardCharsets.UTF_8),false),new Identity(ArtifactType.PARSER_CONFIG,"ama.office-documents.v1"),state));}}}

 @Test void documentManifestBindsItsOwnParserProcessingAndStepAndRejectsLegacyStepSubstitution()throws Exception{
  byte[] parser,processing;try(var in=DocumentImportConfigTest.class.getResourceAsStream("/ama/transcript/document-parser-v1.json")){parser=in.readAllBytes();}try(var in=DocumentImportConfigTest.class.getResourceAsStream("/ama/transcript/document-processing-v1.json")){processing=in.readAllBytes();}
  var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var manifest=mapper.readTree(ConfigWireReaderTest.fixture("manifest"));String parserSha=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(parser)),processingSha=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(processing));
  for(var ref:java.util.List.of(manifest.path("configs").path("parser"),manifest.path("steps").path(0).path("parser"))){((com.fasterxml.jackson.databind.node.ObjectNode)ref).put("version","ama.office-documents.v1").put("sha256",parserSha);}
  for(var ref:java.util.List.of(manifest.path("configs").path("processing"),manifest.path("steps").path(0).path("config"))){((com.fasterxml.jackson.databind.node.ObjectNode)ref).put("version","ama.import-documents.v1").put("sha256",processingSha);}
  ((com.fasterxml.jackson.databind.node.ObjectNode)manifest.path("steps").path(0)).put("kind","IMPORT_DOCUMENT");var originals=new java.util.ArrayList<>(ConfigBindingsTest.archives());originals.removeIf(a->a.claimedArtifactType()==ArtifactType.PARSER_CONFIG||a.claimedArtifactType()==ArtifactType.PROCESSING_CONFIG);originals.add(new RawArchive(ArtifactType.PARSER_CONFIG,"ama.office-documents.v1",parser));originals.add(new RawArchive(ArtifactType.PROCESSING_CONFIG,"ama.import-documents.v1",processing));var binding=ConfigBindingsTest.service().computeProcessing(mapper.writeValueAsBytes(manifest),ConfigBindingsTest.prerequisites(),originals,ConfigWireReaderTest.B,()->false);assertEquals("ama.office-documents.v1",binding.parser().version());
  ((com.fasterxml.jackson.databind.node.ObjectNode)manifest.path("steps").path(0)).put("kind","IMPORT_TXT");assertThrows(ama.contract.MinutesContracts.Failure.class,()->ConfigBindingsTest.service().computeProcessing(mapper.writeValueAsBytes(manifest),ConfigBindingsTest.prerequisites(),originals,ConfigWireReaderTest.B,()->false));
 }
}
